import{_ as i,c as t,o as e,ag as s}from"./chunks/framework.C7v41-tM.js";const k=JSON.parse('{"title":"公开提交前：为什么检查 gitignore 还不够","description":"","frontmatter":{},"headers":[],"relativePath":"notes/git-publication-check.md","filePath":"notes/git-publication-check.md","lastUpdated":null}'),n={name:"notes/git-publication-check.md"};function r(h,a,o,l,p,c){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="公开提交前-为什么检查-gitignore-还不够" tabindex="-1">公开提交前：为什么检查 gitignore 还不够 <a class="header-anchor" href="#公开提交前-为什么检查-gitignore-还不够" aria-label="Permalink to &quot;公开提交前：为什么检查 gitignore 还不够&quot;">​</a></h1><p><code>.gitignore</code> 主要影响未跟踪文件。一个环境配置已经被 Git 跟踪后，补一条忽略规则不会把它自动从提交和历史里移除。</p><h2 id="先看真正要提交的内容" tabindex="-1">先看真正要提交的内容 <a class="header-anchor" href="#先看真正要提交的内容" aria-label="Permalink to &quot;先看真正要提交的内容&quot;">​</a></h2><p>在目标仓库执行以下只读检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span></span></code></pre></div><p>真实差异可能包含秘密，最后一条应在自己的终端审阅，不把原输出粘贴到公开报告。核对配置、会话、数据库、附件、绝对本机路径和提交作者邮箱；文件名含 example 也不保证没有凭据。</p><h2 id="当前文件与旧历史分开处理" tabindex="-1">当前文件与旧历史分开处理 <a class="header-anchor" href="#当前文件与旧历史分开处理" aria-label="Permalink to &quot;当前文件与旧历史分开处理&quot;">​</a></h2><p>取消跟踪可以保留工作区文件，但不会清除旧提交中的内容。若真实密钥曾泄漏，先撤销或轮换，再单独评估历史清理、协作者同步及缓存影响；不要把一次普通提交说成历史已经安全。</p><h2 id="构建产物也要看" tabindex="-1">构建产物也要看 <a class="header-anchor" href="#构建产物也要看" aria-label="Permalink to &quot;构建产物也要看&quot;">​</a></h2><p>源码仓库私有，浏览器 JS 仍可能公开。检查实际 HTML、脚本、搜索索引和附件，确认只含筛选后的内容。公开站点也需要区分网站入口和源码仓库链接，不能用“能访问”证明已经开源。</p><p>参考：<a href="https://git-scm.com/docs/gitignore" target="_blank" rel="noreferrer">Git 忽略规则</a>、<a href="https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/removing-sensitive-data-from-a-repository" target="_blank" rel="noreferrer">GitHub 移除敏感数据</a>。整理：2026-10-14；命令是检查方法，不会自动修复泄漏。</p>`,11)])])}const g=i(n,[["render",r]]);export{k as __pageData,g as default};
